var hosts=UnityEngine.Object.FindObjectsByType<CRPG.Gameplay.Interactions.InteractionControllerBehaviour>(UnityEngine.FindObjectsSortMode.None);
return new {interactions=hosts.Select(h=>new{name=h.name,request=h.Controller.CurrentRequest?.Phase.ToString()}).ToArray(), agents=CRPG.Gameplay.CharacterAgent.AllLive.Select(a=>new{name=a.name,id=a.EntityId.ToString(),pos=a.transform.position.ToString(),motion=a.Motor?.Snapshot.ToString()}).ToArray(),loot=UnityEngine.Object.FindObjectsByType<CRPG.Gameplay.Interactions.Adapters.LootInteractionAdapter>(UnityEngine.FindObjectsSortMode.None).Select(l=>new{name=l.name,empty=l.Container.IsEmpty}).ToArray()};
